-- Afghan AI initial PostgreSQL schema (design artifact; not yet applied).
-- Apply only to a newly provisioned STAGING database after reviewing this file.
-- UUIDs are generated by the application. Never store raw session or invitation tokens.

BEGIN;

CREATE TABLE accounts (
    id UUID PRIMARY KEY,
    email_normalized TEXT UNIQUE,
    phone_normalized TEXT UNIQUE,
    password_hash TEXT,
    email_verified_at TIMESTAMPTZ,
    phone_verified_at TIMESTAMPTZ,
    status TEXT NOT NULL DEFAULT 'invited'
        CHECK (status IN ('invited', 'active', 'locked', 'disabled')),
    mfa_enrolled_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (
        (email_normalized IS NOT NULL AND length(email_normalized) BETWEEN 3 AND 254)
        OR
        (phone_normalized IS NOT NULL AND length(phone_normalized) BETWEEN 7 AND 32)
    ),
    -- These columns must already be normalized by the application before insert.
    CHECK (
        email_normalized IS NULL
        OR (email_normalized = lower(email_normalized) AND email_normalized !~ '[[:space:]]')
    ),
    CHECK (
        phone_normalized IS NULL
        OR phone_normalized ~ '^[+][1-9][0-9]{6,14}$'),
    CHECK (password_hash IS NULL OR length(password_hash) BETWEEN 20 AND 512),
    CHECK (
        status <> 'active'
        OR email_verified_at IS NOT NULL
        OR phone_verified_at IS NOT NULL
    )
);

CREATE TABLE role_assignments (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    role TEXT NOT NULL CHECK (role IN (
        'founder_admin', 'security_admin', 'content_editor',
        'teacher', 'parent_guardian', 'student', 'seller', 'moderator'
    )),
    granted_by UUID REFERENCES accounts(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (account_id, role)
);

CREATE TABLE sessions (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    token_hash CHAR(64) NOT NULL UNIQUE
        CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    csrf_token_hash CHAR(64)
        CHECK (csrf_token_hash IS NULL OR csrf_token_hash ~ '^[0-9a-f]{64}$'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    CHECK (expires_at > created_at)
);

CREATE TABLE bootstrap_invites (
    id UUID PRIMARY KEY,
    token_hash CHAR(64) NOT NULL UNIQUE
        CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    role TEXT NOT NULL CHECK (role IN ('founder_admin', 'security_admin')),
    issued_by UUID REFERENCES accounts(id) ON DELETE SET NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    used_at TIMESTAMPTZ,
    CHECK (expires_at > created_at)
);

CREATE TABLE audit_events (
    id UUID PRIMARY KEY,
    actor_account_id UUID REFERENCES accounts(id) ON DELETE SET NULL,
    action TEXT NOT NULL CHECK (length(action) BETWEEN 1 AND 100),
    target_type TEXT CHECK (target_type IS NULL OR length(target_type) <= 80),
    target_id TEXT CHECK (target_id IS NULL OR length(target_id) <= 128),
    -- Store only allowlisted, non-sensitive metadata. Never log passwords or tokens.
    metadata JSONB NOT NULL DEFAULT '{}'::JSONB,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE guardian_links (
    id UUID PRIMARY KEY,
    guardian_account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    student_account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    relationship_label TEXT CHECK (
        relationship_label IS NULL OR length(relationship_label) <= 40
    ),
    consent_status TEXT NOT NULL DEFAULT 'pending'
        CHECK (consent_status IN ('pending', 'granted', 'withdrawn', 'rejected')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (guardian_account_id <> student_account_id),
    UNIQUE (guardian_account_id, student_account_id)
);

CREATE TABLE learning_progress (
    id UUID PRIMARY KEY,
    account_id UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
    course_key TEXT NOT NULL CHECK (length(course_key) BETWEEN 1 AND 100),
    item_key TEXT NOT NULL CHECK (length(item_key) BETWEEN 1 AND 120),
    progress_percent SMALLINT NOT NULL DEFAULT 0
        CHECK (progress_percent BETWEEN 0 AND 100),
    completed_at TIMESTAMPTZ,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (account_id, course_key, item_key)
);

CREATE INDEX accounts_status_created_idx ON accounts(status, created_at DESC);
CREATE INDEX role_assignments_account_idx ON role_assignments(account_id);
CREATE INDEX sessions_account_expiry_idx ON sessions(account_id, expires_at);
CREATE INDEX sessions_active_expiry_idx ON sessions(expires_at) WHERE revoked_at IS NULL;
CREATE INDEX bootstrap_invites_expiry_idx ON bootstrap_invites(expires_at) WHERE used_at IS NULL;
CREATE INDEX audit_events_created_idx ON audit_events(created_at DESC);
CREATE INDEX audit_events_actor_created_idx ON audit_events(actor_account_id, created_at DESC);
CREATE INDEX guardian_links_student_idx ON guardian_links(student_account_id);
CREATE INDEX learning_progress_account_idx ON learning_progress(account_id);

COMMIT;

